pub fn groups(pairs: List[List[Str]]) -> List[List[Str]] {
  let empty: List[List[Str]] = []
  var gs: List[List[Str]] = empty
  for p in pairs {
    let a = p.get_or(0, "")
    let b = p.get_or(1, "")
    let touched = gs.filter(fn(g) => g.contains(a) or g.contains(b))
    let others = gs.filter(fn(g) => not (g.contains(a) or g.contains(b)))
    let merged = touched.flatten().push(a).push(b)
    gs = others.push(merged)
  }
  let normalized = gs.map(fn(g) => g.unique().sort())
  return normalized.sort_by(fn(g) => g.get_or(0, ""))
}
